// Normalises the three entry points. The schedule always delivers. A manual
// run or a call from another workflow is a dry run unless it passes
// dry_run: false. Optional inputs: use_llm (default true) and date
// (YYYY-MM-DD, replaces today's Europe/Athens date for testing).
const input = $input.first()?.json ?? {};
const scheduled = Object.prototype.hasOwnProperty.call(input, 'timestamp')
  || Object.prototype.hasOwnProperty.call(input, 'Readable date');
const zone = 'Europe/Athens';
let now = DateTime.now().setZone(zone);
if (!scheduled && typeof input.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input.date)) {
  now = DateTime.fromISO(input.date, { zone }).set({ hour: now.hour, minute: now.minute, second: now.second });
}
return [{
  json: {
    job: "gpu-watch",
    scheduled,
    dry_run: scheduled ? false : input.dry_run !== false,
    use_llm: scheduled ? true : input.use_llm !== false,
    now: now.toISO(),
    today: now.toISODate(),
    yesterday: now.minus({ days: 1 }).toISODate(),
    month_start: now.startOf('month').toISODate(),
    weekday: now.setLocale('en').toFormat('cccc'),
  },
}];

// Parses gpu-watchlist.yml (flow list of names, or a block list of names or
// {name, target_price}) and emits one search per product and shop.
// Only shops whose search page is readable without a browser are listed:
// skroutz.gr and bestprice.gr sit behind a bot challenge, public.gr and
// you.gr answer 403, and the web-search service gets nothing from any of them.
const SHOPS = [
  { shop: 'Plaisio', url: (q) => `https://www.plaisio.gr/search?query=${encodeURIComponent(q)}` },
];

const text = String($input.first().json.data ?? '');
const unquote = (s) => String(s).trim().replace(/^(['"])(.*)\1$/, '$2').trim();
const lines = text.split(/\r?\n/).filter((l) => !/^\s*#/.test(l)).map((l) => l.replace(/\s+#.*$/, ''));
const products = [];
const flow = lines.join('\n').match(/^products:\s*\[([\s\S]*?)\]/m);
if (flow) {
  for (const m of flow[1].matchAll(/'([^']*)'|"([^"]*)"|([^,\s'"][^,]*)/g)) {
    const name = (m[1] ?? m[2] ?? m[3] ?? '').trim();
    if (name) products.push({ name });
  }
} else {
  let inProducts = false;
  let current = null;
  for (const line of lines) {
    if (/^products:\s*$/.test(line)) { inProducts = true; continue; }
    if (!inProducts || !line.trim()) continue;
    if (/^\S/.test(line)) break;
    let m = line.match(/^\s*-\s*(.*)$/);
    if (m) {
      current = {};
      products.push(current);
      const rest = m[1];
      const kv = rest.match(/^(\w+):\s*(.*)$/);
      if (kv) current[kv[1]] = unquote(kv[2]);
      else if (rest.trim()) current.name = unquote(rest);
      continue;
    }
    m = line.match(/^\s+(\w+):\s*(.*)$/);
    if (m && current) current[m[1]] = unquote(m[2]);
  }
}
const out = [];
for (const p of products) {
  const name = String(p.name || '').trim();
  if (!name) continue;
  const target = Number(String(p.target_price ?? '').replace(',', '.'));
  for (const s of SHOPS) {
    out.push({ json: { product: name, target_price: Number.isFinite(target) && target > 0 ? target : null, shop: s.shop, url: s.url(name) } });
  }
}
return out;

const MAX_MESSAGE = 3500;

function decodeEntities(text) {
  return String(text ?? '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function oneLine(text, max) {
  let s = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (max && s.length > max) s = `${s.slice(0, max - 1).replace(/\s+\S*$/, '')}…`;
  return s;
}

// Link text must not break the Markdown link.
function linkText(text) {
  return oneLine(text, 160).replace(/\[/g, '(').replace(/\]/g, ')');
}

function errorText(error) {
  if (!error) return 'unknown error';
  if (typeof error === 'string') return oneLine(error, 200);
  return oneLine(error.message || error.description || JSON.stringify(error), 200);
}

// Joins a heading and bullet lines, dropping trailing bullets that would
// exceed the Talk message budget.
function buildMessage(head, lines, footer) {
  let out = head;
  let dropped = 0;
  for (const line of lines) {
    if (out.length + line.length + 1 + (footer ? footer.length + 2 : 0) > MAX_MESSAGE) {
      dropped += 1;
      continue;
    }
    out += `\n${line}`;
  }
  if (dropped) out += `\n- …and ${dropped} more`;
  if (footer) out += `\n\n${footer}`;
  return out;
}

// Reads schema.org Product offers (JSON-LD) from each shop page, keeps
// in-stock graphics cards whose name matches the watchlist entry, and reports
// the lowest price per product. No LLM.
const opt = $('Run options').first().json;
const searches = $('Products').all().map((i) => i.json);
const pages = $input.all().map((i) => i.json);

const norm = (s) => decodeEntities(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const VARIANTS = ['ti', 'xt', 'xtx', 'super', 'gre'];
function matches(query, name) {
  const q = norm(query).split(' ');
  const n = ` ${norm(name)} `;
  if (!q.every((t) => n.includes(` ${t} `))) return false;
  const num = q.find((t) => /^\d{4}$/.test(t));
  if (num) {
    const after = (n.match(new RegExp(` ${num} (\\w+) `)) || [])[1];
    if (after && VARIANTS.includes(after) && !q.includes(after)) return false;
  }
  return !/\b(laptop|notebook|desktop|gaming pc|all in one)\b/.test(n);
}
function products(html) {
  const found = [];
  for (const m of String(html).matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/g)) {
    let data;
    try { data = JSON.parse(m[1]); } catch (e) { continue; }
    const walk = (o) => {
      if (Array.isArray(o)) return o.forEach(walk);
      if (!o || typeof o !== 'object') return;
      if (o['@type'] === 'Product') found.push(o);
      Object.values(o).forEach(walk);
    };
    walk(data);
  }
  return found;
}
function price(value) {
  if (typeof value === 'number') return value;
  const s = String(value ?? '').replace(/[^\d.,]/g, '');
  const n = Number(/,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, ''));
  return Number.isFinite(n) && n > 0 ? n : null;
}

const best = {};
const failures = [];
let readable = 0;
searches.forEach((s, i) => {
  const page = pages[i] || {};
  if (page.error || typeof page.data !== 'string') {
    failures.push(`${s.shop} (${s.product}): ${errorText(page.error || 'no page')}`);
    return;
  }
  readable += 1;
  for (const p of products(page.data)) {
    if (!matches(s.product, p.name || '')) continue;
    for (const offer of [].concat(p.offers || [])) {
      const value = price(offer.price ?? offer.lowPrice);
      if (!value || !/InStock|LimitedAvailability/i.test(String(offer.availability || ''))) continue;
      const url = offer.url || p.url || s.url;
      const current = best[s.product];
      if (!current || value < current.price) {
        best[s.product] = { product: s.product, target: s.target_price, shop: s.shop, price: value, title: decodeEntities(p.name), url };
      }
    }
  }
});
if (searches.length && !readable) throw new Error(`No shop page could be read (${failures.slice(0, 3).join('; ')})`);

const order = [...new Set(searches.map((s) => s.product))];
const rows = order.filter((name) => best[name]).map((name) => {
  const b = best[name];
  const alert = b.target && b.price < b.target;
  const eur = b.price.toLocaleString('el-GR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `- ${alert ? '**ALERT** ' : ''}**${linkText(name)}**: ${eur} € at ${b.shop}, [${linkText(b.title)}](${b.url})${b.target ? ` (target ${b.target} €)` : ''}`;
});
const shops = [...new Set(searches.map((s) => s.shop))].join(', ');
const footer = `_In-stock offers from ${shops}.${failures.length ? ` Not read: ${failures.join('; ')}` : ''}_`;
const message = rows.length ? buildMessage(`### GPU prices, ${opt.today}\n`, rows, footer) : '';
return [{ json: { message, deliver: Boolean(message) && !opt.dry_run, dry_run: opt.dry_run, items: rows.length, searched: searches.length } }];

// Not delivered: a dry run, or nothing to report. Returned to a calling workflow.
const r = $input.first().json;
return [{ json: { ...r, delivered: false, reason: r.message ? 'dry run' : 'nothing to report' } }];

// This workflow is its own error workflow. Only failures of scheduled runs
// are posted; manual runs and dry runs show the error in n8n instead.
const e = $input.first().json;
const execution = e.execution || {};
const mode = String(execution.mode || '');
const node = execution.lastNodeExecuted || execution.error?.node?.name || 'unknown node';
const reason = String(execution.error?.message || execution.error?.description || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 300);
const message = `**${"gpu-watch"} digest failed** (n8n, node "${node}"): ${reason}`;
return [{ json: { message, deliver: mode === 'trigger' || mode === 'webhook', mode } }];
